import smile.stat.hypothesis.CorTest;

public class CorTestSpecialValueRunner {
    static double spearmanRhoAnti(int n){
        double[] x = new double[n];
        double[] y = new double[n];
        for(int i=0;i<n;i++){
            x[i]=i;
            y[i]=(n-1-i);
        }
        return CorTest.spearman(x,y).cor();
    }
    static double kendallTauConcordant(int n){
        double[] x = new double[n];
        double[] y = new double[n];
        for(int i=0;i<n;i++){
            x[i]=i;
            y[i]=i;
        }
        return CorTest.kendall(x,y).cor();
    }

    public static void main(String[] args){
        int[] spearmanNs = new int[]{1290,1291,2000};
        for(int n: spearmanNs){
            double rho = spearmanRhoAnti(n);
            System.out.println("spearman_rho n="+n+" value="+rho);
        }
        int[] kendallNs = new int[]{65537};
        for(int n: kendallNs){
            double tau = kendallTauConcordant(n);
            System.out.println("kendall_tau n="+n+" value="+tau);
        }
    }
}
